import { ConnectionService } from './ConnectionService'
import { ConnectionOptions } from './ConnectionOptions'

@Component
export struct ConnectionSettings {
  @State endpoint: string = ''
  private service: ConnectionService = new ConnectionService()
  private options: ConnectionOptions = { secure: true }

  applyEndpoint(): void {
    if (this.endpoint.trim().length === 0) {
      promptAction.showToast({ message: 'Endpoint is required' })
      return
    }
    this.service.open(this.endpoint, this.options)
  }

  build() { Text(this.endpoint) }
}

